-- ============================================================
-- Migration: real pricing content for the Photography services page
-- Run this once in: Supabase Dashboard (project sedsjjmjnikppfaecaya)
--   -> SQL Editor -> New query -> paste this whole file -> Run
-- Requires 0001_page_content_and_media_bucket.sql to have been run first
-- (this updates a row that migration creates).
--
-- Adds real prices from the studio flyers (walk-in photo/mounting charges,
-- wooden photo mounts, Traditional Wedding Packages, Wedding Quotation) to
-- the existing 'services-photography' page_content row. Uses a jsonb merge
-- (content || new_data) so any hero/categories/packages/cta text an admin
-- has already edited in the Pages tab is left untouched — only these six
-- new keys are added/overwritten. All of it becomes editable from
-- Admin -> Pages -> Services — Photography immediately after this runs
-- (the Wedding Quotation and Traditional Wedding Packages sections also
-- appear on the Videography page, read from this same saved content).
-- Safe to re-run.
-- ============================================================

update mejasan_page_content
set content = content || '{"studioCharges":{"heading":"Photo Studio Charges","description":"Walk-in studio session pricing for single, group, express, and creative portrait photos.","items":[{"label":"Single Photo","price":"Ksh. 350","note":"Delivery within 48 hrs"},{"label":"Group Photo (2–3 people)","price":"Ksh. 400","note":"Delivery within 48 hrs"},{"label":"Group Photo (4–6 people)","price":"Ksh. 500","note":"Delivery within 48 hrs"},{"label":"Group Photo (7–10 people)","price":"Ksh. 800","note":"Delivery within 48 hrs"},{"label":"Express Photo","price":"Ksh. 450","note":"Delivery within 12 hrs"},{"label":"Creative Photo","price":"Ksh. 500","note":"Delivery within 72 hrs"}]},"photoMounting":{"heading":"Photo Mounting Charges","description":"Standard paper photo mounts, priced by size.","items":[{"size":"A1","price":"Ksh. 5,500"},{"size":"A2","price":"Ksh. 3,500"},{"size":"A3","price":"Ksh. 2,500"},{"size":"A4","price":"Ksh. 1,500"},{"size":"A5","price":"Ksh. 600"}]},"studioOffer":{"heading":"Studio Offer","description":"Limited-time bulk print discount.","items":[{"label":"10 pics","wasPrice":"Ksh. 3,500","nowPrice":"Ksh. 3,200"},{"label":"20 pics","wasPrice":"Ksh. 7,000","nowPrice":"Ksh. 6,200"}]},"woodenMount":{"heading":"Wooden Photo Mount","description":"Display your cherished memories with Mejasan Media Production''s handcrafted wooden photo mounts. Elegant, timeless, and perfect for any occasion.","items":[{"size":"A4","price":"Ksh. 1,500"},{"size":"A3","price":"Ksh. 2,500"},{"size":"A2","price":"Ksh. 3,500"},{"size":"A1","price":"Ksh. 5,500"},{"size":"A0","price":"Ksh. 8,000"}]},"traditionalWeddingPackages":{"heading":"Traditional Wedding Packages","description":"Our customised Traditional Wedding packages cater for all your needs, offering a blend of candid shots, posed portraits and artistic compositions.","note":"Premium Cinematic Reels @ Ksh. 20,000, Phone Reel Videos @ Ksh. 10,000, Drone Cinematography @ Ksh. 15,000, Extended Party coverage @ Ksh. 20,000. Logistics and transport costs calculated separately per distance.","packages":[{"label":"1st Package","photographyItems":["Preliminary meeting & consultation","1 Professional Photographer","1 HD Photography Camera","Photography Lights","Unlimited edited soft copy photos","A day coverage"],"photographyPrice":"Ksh. 25,000","printsItems":["Executive A4 Photo book — 150 Photos (8x12)","2 A3 photo mounts"],"printsPrice":"Ksh. 15,000","videographyItems":["1 Professional Videographer","1 HD Video Camera","Well edited full event coverage HD video in a flash drive","Private YouTube link of the uploaded video"],"videographyPrice":"Ksh. 30,000","addOnsItems":[],"total":"Ksh. 70,000"},{"label":"2nd Package","photographyItems":["Preliminary meeting & consultation","2 Professional Photographers","2 HD Photography Cameras","Photography Lights","Unlimited edited soft copy photos","A day coverage"],"photographyPrice":"Ksh. 45,000","printsItems":["Executive A4 Photo book — 200 Photos (12x12)","2 A3, 2 A4 photo mounts"],"printsPrice":"Ksh. 20,000","videographyItems":["2 Professional Videographers","2 4K Video Cameras","Well edited full event coverage HD video in a flash drive","Private YouTube link of the uploaded video"],"videographyPrice":"Ksh. 60,000","addOnsItems":["Drone coverage — Ksh. 15,000"],"total":"Ksh. 140,000"},{"label":"3rd Package","photographyItems":["Preliminary meeting & consultation","3 Professional Photographers","3 HD Photography Cameras","Photography Lights","Unlimited edited soft copy photos","A day coverage"],"photographyPrice":"Ksh. 60,000","printsItems":["2 Executive A4 Photo books — 200 Photos (12x12)","3 A3, 3 A4 photo mounts"],"printsPrice":"Ksh. 40,000","videographyItems":["2 Professional Videographers","2 4K Video Cameras","Well edited full event coverage HD video in a flash drive","Private YouTube link of the uploaded video","5-minute event trailer"],"videographyPrice":"Ksh. 70,000","addOnsItems":["Drone coverage — Ksh. 15,000","Reels — Ksh. 20,000"],"total":"Ksh. 205,000"}]},"weddingQuotation":{"heading":"Wedding Quotation","description":"Full wedding-day photography & videography packages.","packages":[{"label":"1st Package","items":["2 Photographers, cameras & lights","1 Videographer","Unlimited edited soft copy photos","Wedding Photobook (8 by 12)","3 Mounted Photos (1 A3, 2 A4)"],"price":"Ksh. 100,000"},{"label":"2nd Package","items":["2 Photographers, cameras & lights","2 Videographers, cameras & lights","Unlimited edited soft copy photos","Personalised Wedding Photobook (12 by 12)","4 Mounted Photos (1 A2, 1 A3, 2 A4)","Well edited HD full event video in a flash disk and a private YouTube link"],"price":"Ksh. 150,000"},{"label":"3rd Package","items":["2 Photographers, cameras & lights","2 Videographers, cameras & lights","Unlimited edited soft copy photos","Wedding signage book (8 by 12)","3 wedding reels","Wedding Photobook (24 by 18), 40 pages","6 Mounted Photos (2 A2, 2 A3, 2 A4)","Well edited 4K full event video in 2 flash disks and private YouTube link","Wedding trailer","Engagement shoot (photos and video)","Drone service"],"price":"Ksh. 230,000"},{"label":"4th Package","items":["2 Photographers, cameras & lights","3 Videographers, cameras & lights","Unlimited edited soft copy photos","Wedding Signage Book (8 by 12)","5 wedding reels","1 Wedding Photobook (24 by 18), 40 pages & 2 mini Photobooks (for parents)","8 Mounted Photos (1 A1, 2 A2, 3 A3, 2 A4)","Well edited 4K full event video in two flash disks and private YouTube link","Wedding trailer","Engagement shoot (photos and video)","Drone service","After-party / Evening Party coverage"],"price":"Ksh. 305,000"}]}}'::jsonb
